import { useState, useEffect } from 'react';
import api from '../lib/api';
import formatDate from '../lib/formatDate';
import EmptyState from './EmptyState';

export default function NoteCard({ note }) {
  const [tags, setTags] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let active = true;
    api
      .get(`/api/notes/${note?.id}/tags`)
      .then((res) => {
        if (active) setTags(res.data ?? []);
      })
      .catch((err) => {
        if (active) setError(err?.response?.data?.detail ?? 'Failed to load tags');
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [note?.id]);

  const handleDelete = () => {
    api
      .delete(`/api/notes/${note?.id}`)
      .then(() => {
        // TODO: refresh note list
      })
      .catch((err) => {
        setError(err?.response?.data?.detail ?? 'Failed to delete note');
      });
  };

  if (loading) {
    return <div className="p-6 text-center text-gray-500">Loading note…</div>;
  }

  if (error) {
    return <div className="p-6 text-center text-red-600">{error}</div>;
  }

  if (!note) {
    return <EmptyState />;
  }

  return (
    <div className="bg-white rounded-lg shadow-md p-4">
      <h2 className="text-lg font-bold mb-2">{note?.title ?? 'Untitled'}</h2>
      <p className="text-gray-600 mb-4">{note?.content ?? ''}</p>
      <ul className="flex flex-wrap mb-4">
        {tags.map((tag) => (
          <li key={tag?.id} className="mr-2 mb-2 bg-gray-100 rounded-lg px-2 py-1 text-gray-600">
            {tag?.name ?? 'Unknown'}
          </li>
        ))}
      </ul>
      <div className="flex justify-between">
        <span className="text-gray-600 text-xs">{formatDate(note?.created_at ?? '')}</span>
        <button
          className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded-lg"
          onClick={handleDelete}
        >
          Delete
        </button>
      </div>
    </div>
  );
}

